http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rawToken, err := getTokenFromHeader(r)
		if err != nil {
			handleError(r.Context(), err, w)
			return
		}

		token, err := a.jwtParser.Parse(rawToken)
		if err != nil {
			handleError(r.Context(), err, w)
			return
		}
		ctx := jwt.ClaimsToContext(r.Context(), token.Claims)

		next.ServeHTTP(w, r.WithContext(ctx))
	})

