zap.Hooks(func(entry zapcore.Entry) error {
		isErrorLog := entry.Level == zap.ErrorLevel || entry.Level == zap.PanicLevel
		if isErrorLog {
			sentry.CaptureMessage(entry.Message)
		}
		return nil
	})

