sort.Slice(ids, func(i, j int) bool {
		if less := ShouldSortMarketAuthIdentifierVariantBefore(ids[i], ids[j]); less {
			return true
		}
		if less := ShouldSortMarketAuthIdentifierVariantBefore(ids[j], ids[i]); less {
			return false
		}

		// Finally by carType
		return ids[i].carType < ids[j].carType
	})

sort.Slice(ids, func(i, j int) bool {
		return ShouldSortMarketAuthIdentifierVariantBefore(ids[i], ids[j])
	})

sort.Slice(sorted, func(left, right int) bool {
		return sorted[left].From.Before(sorted[right].From)
	})

sort.Slice(sortedEdges, func(i, j int) bool {
		return sortedEdges[i].Before(sortedEdges[j])
	})

