			logger.Error(
				"message ended in poison queue",
				errors.New("message ended in poison queue"),
				nil,
			)
			return nil
		})

message.NoPublishHandlerFunc(func(msg *message.Message) error {
			msgType := msg.Metadata.Get(TypeHeaderKey)
			switch msgType {
			case MarketAuthMessage:
				return handler.HandleMarketAuthMessage(msg)
			default:
				logger.Warnw(msg.Context(), "Unknown message type", "type", msgType)
			}
			return nil
		})

