zap.WrapCore(func(existing zapcore.Core) zapcore.Core {
		otelCore := withLevel(
			spanContextCore{
				inner: otelzap.NewCore(cfg.ServiceName, otelzap.WithLoggerProvider(cfg.Provider)),
			},
			cfg.Level,
		)

		if cfg.TakeOverConsole {
			return otelCore
		}

		return zapcore.NewTee(existing, otelCore)
	})
